CREATE OR REPLACE FUNCTION public.psb_current_seller_id()
 RETURNS text
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
  SELECT seller_id
  FROM public.psb_user_roles
  WHERE user_id = auth.uid();
$function$
CREATE OR REPLACE FUNCTION public.psb_guard_seller_order_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_is_admin boolean := false;
  v_seller_id text;
  v_payment_released boolean;
begin
  v_is_admin := public.psb_is_admin();
  if v_is_admin then
    return new;
  end if;

  if auth.role() <> 'authenticated' then
    raise exception 'order update requires authenticated user';
  end if;

  v_seller_id := public.psb_current_seller_id();
  if v_seller_id is null or old.seller_id is distinct from v_seller_id then
    raise exception 'seller cannot update this order';
  end if;

  if new.order_number is distinct from old.order_number
     or new.seller_id is distinct from old.seller_id
     or new.seller_name is distinct from old.seller_name
     or new.customer is distinct from old.customer
     or new.items is distinct from old.items
     or new.subtotal is distinct from old.subtotal
     or new.source is distinct from old.source
     or new.created_at is distinct from old.created_at then
    raise exception 'seller may update only order workflow status';
  end if;

  v_payment_released := new.status in ('aprovado-para-pagamento','pago','em-separacao','enviado','concluido');
  new.payment_released := v_payment_released;
  new.updated_at := now();

  if new.status is distinct from old.status then
    new.timeline := coalesce(old.timeline, '[]'::jsonb) || jsonb_build_array(
      jsonb_build_object(
        'status', new.status,
        'at', new.updated_at,
        'note', 'Status atualizado pela loja.'
      )
    );
  else
    new.timeline := old.timeline;
  end if;

  new.order_payload := coalesce(old.order_payload, '{}'::jsonb)
    || jsonb_build_object(
      'status', new.status,
      'paymentReleased', new.payment_released,
      'updatedAt', new.updated_at,
      'timeline', new.timeline
    );

  return new;
end;
$function$
CREATE OR REPLACE FUNCTION public.psb_html_escape_jsonb(p_value jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_type text;
  v_result jsonb;
begin
  v_type := jsonb_typeof(p_value);

  if v_type = 'string' then
    return to_jsonb(public.psb_html_escape_text(p_value #>> '{}'));
  elsif v_type = 'array' then
    select coalesce(jsonb_agg(public.psb_html_escape_jsonb(value)), '[]'::jsonb)
      into v_result
      from jsonb_array_elements(p_value);
    return v_result;
  elsif v_type = 'object' then
    select coalesce(jsonb_object_agg(key, public.psb_html_escape_jsonb(value)), '{}'::jsonb)
      into v_result
      from jsonb_each(p_value);
    return v_result;
  else
    return p_value;
  end if;
end;
$function$
CREATE OR REPLACE FUNCTION public.psb_html_escape_text(p_value text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE STRICT
 SET search_path TO 'pg_catalog'
AS $function$
  select replace(
           replace(
             replace(
               replace(
                 replace(p_value, '&', '&amp;'),
               '<', '&lt;'),
             '>', '&gt;'),
           '"', '&quot;'),
         '''', '&#39;');
$function$
CREATE OR REPLACE FUNCTION public.psb_is_admin()
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.psb_user_roles
    WHERE user_id = auth.uid()
      AND role = 'admin'
  );
$function$
CREATE OR REPLACE FUNCTION public.psb_order_items_valid(p_items jsonb, p_seller_id text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_item jsonb;
  v_qty numeric;
  v_preco numeric;
  v_slug text;
  v_item_seller text;
begin
  if jsonb_typeof(p_items) <> 'array' then
    return false;
  end if;

  if jsonb_array_length(p_items) < 1 or jsonb_array_length(p_items) > 200 then
    return false;
  end if;

  for v_item in select value from jsonb_array_elements(p_items)
  loop
    if jsonb_typeof(v_item) <> 'object' then
      return false;
    end if;

    if not (v_item ? 'nome' and v_item ? 'qty' and v_item ? 'preco') then
      return false;
    end if;

    if length(btrim(coalesce(v_item ->> 'nome',''))) < 1
       or length(v_item ->> 'nome') > 200
       or length(coalesce(v_item ->> 'variacao','')) > 240
       or length(coalesce(v_item ->> 'sellerName','')) > 160
       or length(coalesce(v_item ->> 'sellerLabel','')) > 200
       or length(coalesce(v_item ->> 'key','')) > 300
       or length(coalesce(v_item ->> 'img','')) > 500 then
      return false;
    end if;

    v_slug := coalesce(v_item ->> 'slug','');
    if v_slug <> '' and (length(v_slug) > 120 or v_slug !~ '^[a-z0-9][a-z0-9-]*$') then
      return false;
    end if;

    v_item_seller := coalesce(v_item ->> 'sellerId','');
    if v_item_seller <> '' and v_item_seller <> p_seller_id then
      return false;
    end if;

    begin
      v_qty := (v_item ->> 'qty')::numeric;
      v_preco := (v_item ->> 'preco')::numeric;
    exception when others then
      return false;
    end;

    if v_qty < 1 or v_qty > 10000 or trunc(v_qty) <> v_qty then
      return false;
    end if;

    if v_preco < 0 or v_preco > 1000000 then
      return false;
    end if;
  end loop;

  return true;
end;
$function$
CREATE OR REPLACE FUNCTION public.psb_sanitize_order_html()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
begin
  new.seller_name := public.psb_html_escape_text(coalesce(new.seller_name, ''));
  new.customer := public.psb_html_escape_jsonb(new.customer);
  new.items := public.psb_html_escape_jsonb(new.items);
  new.timeline := public.psb_html_escape_jsonb(new.timeline);
  new.order_payload := public.psb_html_escape_jsonb(new.order_payload);
  return new;
end;
$function$
CREATE OR REPLACE FUNCTION public.psb_set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$function$
CREATE OR REPLACE FUNCTION public.psb_strip_legacy_seller_secrets()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
  NEW.password := NULL;
  NEW.seller_payload := COALESCE(NEW.seller_payload, '{}'::jsonb)
    - 'password' - 'senha' - 'pin' - 'adminPin' - 'access_pin';
  RETURN NEW;
END;
$function$
CREATE OR REPLACE FUNCTION public.psb_write_security_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  v_key text;
  v_details jsonb := '{}'::jsonb;
BEGIN
  IF TG_TABLE_NAME = 'psb_sellers' THEN
    v_key := COALESCE(NEW.seller_id, OLD.seller_id);
    v_details := jsonb_build_object(
      'seller_id', v_key,
      'status_before', CASE WHEN TG_OP <> 'INSERT' THEN OLD.status ELSE NULL END,
      'status_after', CASE WHEN TG_OP <> 'DELETE' THEN NEW.status ELSE NULL END,
      'login_before', CASE WHEN TG_OP <> 'INSERT' THEN OLD.login ELSE NULL END,
      'login_after', CASE WHEN TG_OP <> 'DELETE' THEN NEW.login ELSE NULL END
    );
  ELSIF TG_TABLE_NAME = 'psb_seller_offers' THEN
    v_key := COALESCE(NEW.offer_key, OLD.offer_key);
    v_details := jsonb_build_object(
      'offer_key', v_key,
      'seller_id', COALESCE(NEW.seller_id, OLD.seller_id),
      'scope', COALESCE(NEW.scope, OLD.scope),
      'product_slug', COALESCE(NEW.product_slug, OLD.product_slug),
      'category_slug', COALESCE(NEW.category_slug, OLD.category_slug),
      'active_before', CASE WHEN TG_OP <> 'INSERT' THEN OLD.active ELSE NULL END,
      'active_after', CASE WHEN TG_OP <> 'DELETE' THEN NEW.active ELSE NULL END
    );
  ELSIF TG_TABLE_NAME = 'psb_seller_shipping_settings' THEN
    v_key := COALESCE(NEW.seller_id, OLD.seller_id);
    v_details := jsonb_build_object(
      'seller_id', v_key,
      'origin_city', COALESCE(NEW.origin_city, OLD.origin_city),
      'origin_uf', COALESCE(NEW.origin_uf, OLD.origin_uf),
      'allow_external_shipping_before', CASE WHEN TG_OP <> 'INSERT' THEN OLD.allow_external_shipping ELSE NULL END,
      'allow_external_shipping_after', CASE WHEN TG_OP <> 'DELETE' THEN NEW.allow_external_shipping ELSE NULL END,
      'active_before', CASE WHEN TG_OP <> 'INSERT' THEN OLD.active ELSE NULL END,
      'active_after', CASE WHEN TG_OP <> 'DELETE' THEN NEW.active ELSE NULL END
    );
  ELSIF TG_TABLE_NAME = 'psb_seller_shipping_rules' THEN
    v_key := COALESCE(NEW.rule_key, OLD.rule_key);
    v_details := jsonb_build_object(
      'rule_key', v_key,
      'seller_id', COALESCE(NEW.seller_id, OLD.seller_id),
      'scope', COALESCE(NEW.scope, OLD.scope),
      'product_slug', COALESCE(NEW.product_slug, OLD.product_slug),
      'category_slug', COALESCE(NEW.category_slug, OLD.category_slug),
      'active_before', CASE WHEN TG_OP <> 'INSERT' THEN OLD.active ELSE NULL END,
      'active_after', CASE WHEN TG_OP <> 'DELETE' THEN NEW.active ELSE NULL END
    );
  ELSIF TG_TABLE_NAME = 'psb_user_roles' THEN
    v_key := COALESCE(NEW.user_id, OLD.user_id)::text;
    v_details := jsonb_build_object(
      'user_id', v_key,
      'role_before', CASE WHEN TG_OP <> 'INSERT' THEN OLD.role ELSE NULL END,
      'role_after', CASE WHEN TG_OP <> 'DELETE' THEN NEW.role ELSE NULL END,
      'seller_id_before', CASE WHEN TG_OP <> 'INSERT' THEN OLD.seller_id ELSE NULL END,
      'seller_id_after', CASE WHEN TG_OP <> 'DELETE' THEN NEW.seller_id ELSE NULL END
    );
  ELSIF TG_TABLE_NAME = 'psb_orders' THEN
    v_key := COALESCE(NEW.order_number, OLD.order_number);
    v_details := jsonb_build_object(
      'order_number', v_key,
      'seller_id', COALESCE(NEW.seller_id, OLD.seller_id),
      'status_before', CASE WHEN TG_OP <> 'INSERT' THEN OLD.status ELSE NULL END,
      'status_after', CASE WHEN TG_OP <> 'DELETE' THEN NEW.status ELSE NULL END,
      'payment_released_before', CASE WHEN TG_OP <> 'INSERT' THEN OLD.payment_released ELSE NULL END,
      'payment_released_after', CASE WHEN TG_OP <> 'DELETE' THEN NEW.payment_released ELSE NULL END
    );
  ELSE
    v_key := NULL;
    v_details := jsonb_build_object('table', TG_TABLE_NAME);
  END IF;

  INSERT INTO public.psb_security_audit_log(table_name, action, record_key, actor_uid, actor_role, details)
  VALUES (TG_TABLE_NAME, TG_OP, v_key, auth.uid(), auth.role(), v_details);

  RETURN COALESCE(NEW, OLD);
END;
$function$
